const players = [
  { id: 1, name: 'Ada', level: 7, badge: 'Algoritmos' },
  { id: 2, name: 'Linus', level: 4, badge: 'Kernel' },
  { id: 3, name: 'Grace', level: 9, badge: 'Compiladores' },
];

function PlayerCard({ name, level, badge }) {
  return (
    <article className="card">
      <h2>{name}</h2>
      <p>Nivel {level}</p>
      <span>{badge}</span>
    </article>
  );
}

export default function App() {
  return (
    <section>
      {players.map((player) => (
        <PlayerCard
          key={player.id}
          name={player.name}
          level={player.level}
          badge={player.badge}
        />
      ))}
    </section>
  );
}
